'use strict';
// All processing is local. Models are served from this site's own origin.
let originalPhoto=null,photoMask=null,photoRevision=0,segmenterPromise=null;
function resetPhotoTools(photo){originalPhoto=photo;photoMask=null;photoRevision++;state.cutout=false;['exposure','contrast','warmth','saturation'].forEach(id=>$('#'+id).value=0);$('#compare-original').checked=false;$('#cutout-edge').value=50;$('#cutout-soft').value=12;$('#cutout-status').textContent=photo?'Foto original preservada.':'Envie uma foto para começar.';$('#mask-tuning').hidden=true;$('#remove-bg').disabled=!photo;}
async function getSegmenter(){if(!segmenterPromise){segmenterPromise=(async()=>{const {FilesetResolver,ImageSegmenter}=await import('./vendor/mediapipe/vision_bundle.mjs');const files=await FilesetResolver.forVisionTasks('./vendor/mediapipe/wasm');return ImageSegmenter.createFromOptions(files,{baseOptions:{modelAssetPath:'./vendor/mediapipe/selfie_segmenter.tflite',delegate:'CPU'},runningMode:'IMAGE',outputConfidenceMasks:true,outputCategoryMask:false});})().catch(e=>{segmenterPromise=null;throw e;});}return segmenterPromise;}
function photoCanvas(photo,max=1800){const c=document.createElement('canvas'),ratio=Math.min(1,max/Math.max(photo.width,photo.height));c.width=Math.round(photo.width*ratio);c.height=Math.round(photo.height*ratio);c.getContext('2d').drawImage(photo,0,0,c.width,c.height);return c;}
function applyPhotoTools(){if(!originalPhoto)return;const compare=$('#compare-original').checked;if(compare){state.photo=originalPhoto;state.cutout=false;renderPreview();return;}const c=photoCanvas(originalPhoto),ctx=c.getContext('2d'),pixels=ctx.getImageData(0,0,c.width,c.height),d=pixels.data;
const exposure=2**(Number($('#exposure').value)/100),contrast=1+Number($('#contrast').value)/100,warmth=Number($('#warmth').value)*.55,saturation=1+Number($('#saturation').value)/100;
for(let i=0;i<d.length;i+=4){let r=(d[i]*exposure-128)*contrast+128+warmth,g=(d[i+1]*exposure-128)*contrast+128,b=(d[i+2]*exposure-128)*contrast+128-warmth;const l=.2126*r+.7152*g+.0722*b;d[i]=l+(r-l)*saturation;d[i+1]=l+(g-l)*saturation;d[i+2]=l+(b-l)*saturation;}
ctx.putImageData(pixels,0,0);
if(photoMask){const mask=document.createElement('canvas');mask.width=photoMask.width;mask.height=photoMask.height;const mctx=mask.getContext('2d'),im=mctx.createImageData(mask.width,mask.height),threshold=Number($('#cutout-edge').value)/100,soft=Number($('#cutout-soft').value)/100;for(let i=0;i<photoMask.data.length;i++){const t=Math.max(0,Math.min(1,(photoMask.data[i]-(threshold-soft))/Math.max(.005,soft*2)));im.data[i*4+3]=255*t*t*(3-2*t);}mctx.putImageData(im,0,0);ctx.globalCompositeOperation='destination-in';ctx.drawImage(mask,0,0,c.width,c.height);ctx.globalCompositeOperation='source-over';}
state.photo=c;state.cutout=!!photoMask;renderPreview();}
$('#remove-bg').onclick=async()=>{if(!originalPhoto)return;const source=originalPhoto,revision=photoRevision,button=$('#remove-bg');button.disabled=true;$('#cutout-status').textContent='Carregando o recorte no seu aparelho…';try{const model=await getSegmenter();if(revision!==photoRevision)return;$('#cutout-status').textContent='Separando a pessoa do fundo…';await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));const input=photoCanvas(source,1024);let result;model.segment(input,r=>{const masks=r.confidenceMasks;const mask=masks?.length===1?masks[0]:masks?.[1];if(!mask)throw Error('Máscara indisponível');result={width:mask.width,height:mask.height,data:new Float32Array(mask.getAsFloat32Array())};});if(revision!==photoRevision)return;let count=0;for(const p of result.data)if(p>.5)count++;if(count<result.data.length*.005)throw Error('Pessoa não encontrada');photoMask=result;$('#compare-original').checked=false;$('#mask-tuning').hidden=false;applyPhotoTools();$('#cutout-status').textContent='Recorte aplicado. Confira cabelos e bordas antes de baixar.';}catch(e){console.error('Falha no recorte local:',e);if(revision===photoRevision){$('#cutout-status').textContent=e.message==='Pessoa não encontrada'?'Não foi possível identificar a pessoa. Tente um retrato mais próximo; o original foi mantido.':'O recorte local falhou ao processar a imagem. Recarregue a página e tente novamente; o original foi mantido.';}}finally{button.disabled=!originalPhoto;}};
let photoFrame;['exposure','contrast','warmth','saturation','cutout-edge','cutout-soft'].forEach(id=>$('#'+id).addEventListener('input',()=>{cancelAnimationFrame(photoFrame);photoFrame=requestAnimationFrame(applyPhotoTools);}));
$('#compare-original').onchange=applyPhotoTools;
$('#restore-photo').onclick=()=>{if(!originalPhoto)return;state.photo=originalPhoto;resetPhotoTools(originalPhoto);renderPreview();};
$('#natural-photo').onclick=()=>{if(!originalPhoto)return;$('#exposure').value=8;$('#contrast').value=5;$('#warmth').value=3;$('#saturation').value=3;$('#compare-original').checked=false;applyPhotoTools();};
